-- Publishes the dialogue a-new-neighbour (unit meeting-people). Made by
-- scripts/generate/pipeline.py publish from content/drafts/a-new-neighbour. Do not edit by hand:
-- change the draft, get the changed items reviewed again and publish again.
-- Job 7-content-pipeline, "Done when" 15. Order (docs/data-model.md): forms, then
-- the lines with their words, then the dialogue, then the unit. Running it a second
-- time does nothing, because the dialogue is then already approved.
do $publish$
declare
  v_unit_id bigint;
  v_dialogue_id bigint;
  v_line_id bigint;
  v_status public.content_status;
begin
  if exists (select 1 from public.dialogues
    where slug = 'a-new-neighbour' and status = 'approved') then
    raise notice 'dialogue % is already published; nothing to do', 'a-new-neighbour';
    return;
  end if;

  -- The unit, as a draft until the end.
  insert into public.units (slug, position, title_en, can_do_en, stop_number)
  select s.slug, s.number, s.name_en, s.can_do_en, s.number from public.road_stops s
  where s.number = 1
  on conflict (slug) do nothing;
  select id, status into strict v_unit_id, v_status from public.units
  where slug = 'meeting-people' and position = 1 and stop_number = 1;
  if v_status = 'retired' then
    raise exception 'unit % is retired', 'meeting-people';
  end if;

  -- The dialogue, as a draft until its lines are approved.
  insert into public.dialogues (unit_id, slug, position, title_en)
  values (v_unit_id, 'a-new-neighbour', 3,
    'A new neighbour')
  on conflict (slug) do nothing;
  select id into strict v_dialogue_id from public.dialogues
  where slug = 'a-new-neighbour' and unit_id = v_unit_id and status = 'draft'
    and position = 3 and title_en = 'A new neighbour';
  if exists (select 1 from public.dialogue_lines where dialogue_id = v_dialogue_id) then
    raise exception 'dialogue % already has lines; fix them through the review rounds',
      'a-new-neighbour';
  end if;

